#include <bits/stdc++.h>
using namespace std;

struct Node {
    int value;
    int length;
    int next;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n;
    cin >> m >> n;

    vector<int> a(m + 1);
    for (int i = 1; i <= m; ++i) {
        cin >> a[i];
    }

    int total = m * n;
    vector<Node> b(total + 1);

    for (int i = 1; i <= total; ++i) {
        b[i] = {a[(i - 1) % m + 1], 1, 0};
    }

    for (int i = total - 1; i >= 1; --i) {
        int bestLength = 0;
        int nextIndex = 0;

        for (int j = i + 1; j <= total; ++j) {
            if (b[j].value >= b[i].value && b[j].length >= bestLength) {
                bestLength = b[j].length;
                nextIndex = j;
            }
        }

        if (bestLength > 0) {
            b[i].length = bestLength + 1;
            b[i].next = nextIndex;
        }
    }

    int index = 1;
    for (int i = 1; i <= total; ++i) {
        if (b[i].length >= b[index].length) {
            index = i;
        }
    }

    int answer = 0;
    while (index != 0) {
        ++answer;
        index = b[index].next;
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int m, n, k, l, ans;
int a[200005];
int b[200005][4];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> m >> n;
    for (int i = 1; i <= m; ++i) {
        cin >> a[i];
    }

    int e = 0;
    for (int i = 1; i <= m * n; ++i) {
        ++e;
        b[i][1] = a[e];
        b[i][2] = 1;
        b[i][3] = 0;
        if (e == m) e = 0;
    }

    for (int i = m * n - 1; i >= 1; --i) {
        l = k = 0;
        for (int j = i + 1; j <= m * n; ++j) {
            if (b[j][1] >= b[i][1] && b[j][2] >= l) {
                l = b[j][2];
                k = j;
            }
        }
        if (l > 0) {
            b[i][2] = l + 1;
            b[i][3] = k;
        }
    }

    k = 1;
    for (int j = 1; j <= m * n; ++j) {
        if (b[j][2] >= b[k][2]) k = j;
    }

    while (k != 0) {
        ++ans;
        k = b[k][3];
    }

    cout << ans;
    return 0;
}

